"""Thin wrapper around the identity-verification vendor CLI (vendor/bin/idchk)."""
import os
import subprocess
import tempfile

from hbonboard.models import JobTicket, VendorError

# the vendor answers this for a reference it has no verdict for
NO_RESULT = "E31"
# idchk 3.2.x judges only the first 12 lines of a batch and silently drops the rest
MAX_BATCH_LINES = 12


class IdchkClient:
    def __init__(self, settings):
        self.binary = settings.idchk_bin
        self.home = settings.idchk_home or os.environ.get("IDCHK_HOME", "")
        self.timeout = settings.idchk_timeout

    def _run(self, *args):
        env = dict(os.environ)
        if self.home:
            env["IDCHK_HOME"] = self.home
        proc = subprocess.run(
            [self.binary, *args],
            capture_output=True,
            text=True,
            encoding="utf-8",
            env=env,
            timeout=self.timeout,
        )
        if proc.returncode != 0:
            code = (proc.stderr.strip().splitlines() or ["E??"])[-1]
            raise VendorError(code, args[0])
        return proc.stdout

    def submit(self, requests):
        """Send one batch file; returns the vendor job ticket."""
        if len(requests) > MAX_BATCH_LINES:
            raise ValueError(f"a vendor batch takes at most {MAX_BATCH_LINES} lines, got {len(requests)}")
        lines = [f"{r.ref}\t{r.name}\t{r.birth}\t{r.phone}" for r in requests]
        fd, path = tempfile.mkstemp(prefix="idchk-", suffix=".tsv")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                f.write("\n".join(lines) + "\n")
            out = self._run("batch", "--in", path)
        finally:
            os.unlink(path)
        job_id, _, count = out.strip().partition("\t")
        if not job_id.startswith("J") or not count.isdigit():
            raise VendorError("E??", "batch")
        if int(count) != len(lines):
            # the vendor read a different number of lines than we wrote
            raise VendorError("E??", "batch")
        return JobTicket(job_id, int(count))

    def result(self, ref):
        """Verdict code for a reference, or None while the vendor has none."""
        try:
            out = self._run("result", ref)
        except VendorError as exc:
            if exc.code == NO_RESULT:
                return None
            raise
        fields = dict(line.split(" ", 1) for line in out.splitlines() if " " in line)
        return int(fields["v"])

    def job(self, job_id):
        out = self._run("job", job_id)
        return dict(line.split(" ", 1) for line in out.splitlines() if " " in line)

"""Identity-check run: sends new members to the vendor and applies verdicts."""
from hbonboard.kyc.requests import build_batch
from hbonboard.kyc.verdicts import apply_verdict
from hbonboard.models import KYC_NEW, KYC_SENT


class VerificationService:
    def __init__(self, repo, client, settings, notifier=None, on_resolved=None):
        self.repo = repo
        self.client = client
        self.settings = settings
        self.notifier = notifier
        self.on_resolved = on_resolved

    def _send_new(self):
        fresh = sorted(self.repo.by_kyc_state(KYC_NEW), key=lambda m: m.member_id)
        if not fresh:
            return [], 0
        ticket = self.client.submit(build_batch(fresh))
        for member in fresh:
            member.kyc_state = KYC_SENT
            member.kyc_job = ticket.job_id
            member.history.append(KYC_SENT)
        return [ticket.job_id], len(fresh)

    def _collect(self):
        resolved, waiting = [], []
        for member in sorted(self.repo.by_kyc_state(KYC_SENT), key=lambda m: m.member_id):
            code = self.client.result(member.member_id)
            if code is None:
                # the vendor has not answered for this one yet; ask again next run
                waiting.append(member.member_id)
                continue
            apply_verdict(member, code)
            if self.notifier:
                self.notifier.verdict(member)
            resolved.append({"id": member.member_id, "status": member.status})
        return resolved, waiting

    def run(self):
        jobs, sent = self._send_new()
        resolved, waiting = self._collect()
        if resolved and self.on_resolved:
            self.on_resolved()
        return {"jobs": jobs, "sent": sent, "resolved": resolved, "waiting": len(waiting)}
